async function cmdNewProject() {
  if (!invoke) {
    toast("新增專案需 Tauri IPC（瀏覽器模式無法建立本機目錄／NOT RUN）");
    setStatus("新增專案：無 IPC／NOT RUN");
    return;
  }
  try {
    const nameRaw = window.prompt("新專案資料夾名稱", "NewProject");
    if (nameRaw === null) {
      toast("已取消新增專案");
      setStatus("新增專案：已取消（名稱）");
      return;
    }
    const name = String(nameRaw).trim();
    if (!name) {
      toast("新增專案失敗：名稱不可為空");
      setStatus("新增專案失敗：空名稱");
      return;
    }
    setStatus("新增專案：請選擇父資料夾…");
    const parentPick = await invoke("host_pick_project_directory");
    if (!parentPick || parentPick.status === "cancelled") {
      const msg =
        (parentPick && parentPick.message) || "已取消新增專案（父目錄）";
      toast(msg);
      setStatus(msg);
      return;
    }
    if (parentPick.status !== "ok" || !(parentPick.path || "").trim()) {
      const msg =
        (parentPick && parentPick.message) || "新增專案失敗：父目錄無效";
      toast(msg);
      setStatus(msg);
      return;
    }
    const preferenceChoice = await window.ProjectPreferencesUI.chooseNewProject();
    if (!preferenceChoice) {
      toast("已取消新增專案（偏好設定）");
      return;
    }
    const created = await invoke("host_create_project_with_preferences", {
      args: {
        parent: String(parentPick.path).trim(),
        name: name,
        presetId: preferenceChoice.presetId,
        importedJson: preferenceChoice.importedJson,
      },
    });
    try {
      await bindPickedProjectRoot(created, "新增專案");
    } catch (bindError) {
      const msg="專案目錄已建立，但未完成專案綁定："+String(bindError);
      toast(msg);setStatus(msg);
    }
  } catch (err) {
    const msg = "新增專案失敗：" + String(err);
    toast(msg);
    setStatus(msg);
  }

pub fn create_project_with_preferences(
    fs: &dyn FileSystemPort,
    root: &str,
    choice: PreferenceChoice<'_>,
) -> Result<CreationOutcome, ProjectPreferenceError> {
    let (root, _) = root_path(root)?;
    // Validate before creating anything. Imported data is already captured; this
    // use case has no source-path write capability and never copies credentials.
    let prepared = match choice {
        PreferenceChoice::Skip => None,
        PreferenceChoice::Preset(id) => Some(
            sgenaxis_spec::project_preferences::preset(id)
                .map_err(ProjectPreferenceError::Policy)?,
        ),
        PreferenceChoice::Imported(bytes) => {
            Some(parse_project_preferences(bytes).map_err(ProjectPreferenceError::Policy)?)
        }
    };
    if fs.exists(&root).map_err(ProjectPreferenceError::Storage)? {
        return Err(ProjectPreferenceError::ExistingTarget);
    }
    fs.create_dir_all(&root)
        .map_err(ProjectPreferenceError::Storage)?;
    match prepared {
        None => Ok(CreationOutcome::Created {
            project_root: root,
            preferences: None,
        }),
        Some(draft) => match save_project_preferences(fs, &root, None, &draft) {
            Ok(view) => Ok(CreationOutcome::Created {
                project_root: root,
                preferences: Some(view),
            }),
            Err(error) => Ok(CreationOutcome::DirectoryCreatedPreferencesFailed {
                project_root: root,
                error,
            }),
        },
    }

/// Create (or ensure) a project directory through [`FileSystemPort`].
///
/// If `path` already exists as a **file** (e.g. Save-dialog residue), removes it
/// via [`FileSystemPort::remove_file`] then [`FileSystemPort::create_dir_all`].
///
/// Returns the normalized absolute／local path string suitable for
/// `HostSettings.project_root`. Does **not** mutate settings.
pub fn create_new_project_root(fs: &dyn FileSystemPort, raw: &str) -> Result<String, HostError> {
    let path = normalize_new_project_path(raw)?;
    if fs.is_file(&path).unwrap_or(false) {
        fs.remove_file(&path).map_err(|e| {
            HostError::Settings(format!("無法移除殘留檔「{path}」以便建立目錄：{e}"))
        })?;
    }
    fs.create_dir_all(&path)
        .map_err(|e| HostError::Settings(format!("無法建立專案目錄「{path}」：{e}")))?;
    Ok(path)
}

/// Create under `parent`/`name` (PD-BUG-FILE-NEW-01).
pub fn create_new_project_under(
    fs: &dyn FileSystemPort,
    parent: &str,
    name: &str,
) -> Result<String, HostError> {
    let path = join_new_project_path(parent, name)?;
    create_new_project_root(fs, &path)
}

